// Permanent Lost & Found QR destination. The public code is created once with
// the item and never regenerated by opening, downloading, or printing a label.
const configuredOrigin = import.meta.env?.VITE_PUBLIC_APP_URL
const detectedLanHost = import.meta.env?.VITE_DETECTED_LAN_HOST || ''

function parsedOrigin(value) {
  try {
    const url = new URL(String(value || ''))
    if (!['http:', 'https:'].includes(url.protocol)) return null
    return url
  } catch {
    return null
  }
}

function isLoopback(hostname) {
  const host = String(hostname || '').replace(/^\[|\]$/g, '').toLowerCase()
  return host === 'localhost' || host === '::1' || host === '0.0.0.0' || host.startsWith('127.')
}

function isPrivateIpv4(hostname) {
  const octets = String(hostname || '').split('.').map(Number)
  if (octets.length !== 4 || octets.some((part) => !Number.isInteger(part) || part < 0 || part > 255)) return false
  return octets[0] === 10 || (octets[0] === 172 && octets[1] >= 16 && octets[1] <= 31) || (octets[0] === 192 && octets[1] === 168)
}

export function resolveLostFoundPublicOrigin({
  currentOrigin = globalThis.location?.origin,
  configured = configuredOrigin,
  lanHost = detectedLanHost,
} = {}) {
  const current = parsedOrigin(currentOrigin)
  if (current && !isLoopback(current.hostname)) return current.origin

  const configuredUrl = parsedOrigin(configured)
  if (configuredUrl && !isLoopback(configuredUrl.hostname) && !isPrivateIpv4(configuredUrl.hostname)) {
    return configuredUrl.origin
  }

  if (lanHost) {
    const reachable = current || configuredUrl || new URL('http://localhost')
    reachable.hostname = String(lanHost).trim()
    return reachable.origin
  }

  if (configuredUrl && !isLoopback(configuredUrl.hostname)) return configuredUrl.origin
  throw new Error('A phone-reachable HOSIS address is unavailable. Connect this computer to the hotel Wi-Fi and restart the frontend.')
}

export function buildLostFoundQrPayload(item, origin) {
  const code = String(item?.public_code || '').trim().toLowerCase()
  if (!/^(?:[a-f0-9]{32}|[a-f0-9-]{36})$/.test(code)) {
    throw new Error('This item does not have a valid permanent QR code yet.')
  }
  const base = (origin ? parsedOrigin(origin)?.origin : resolveLostFoundPublicOrigin())
  if (!base) throw new Error('The HOSIS address is required for the QR code.')
  return `${base}/#/lost-found/item/${encodeURIComponent(code)}`
}
